import marshmallow

def check_marshmallow_export():
    expected_exports = {
        'Schema',
        'fields',
        'Raw',
        'TitleCase'
    }

    actual_exports = set(marshmallow.__all__)

    missing_exports = expected_exports - actual_exports
    extra_exports = actual_exports - expected_exports

    if missing_exports:
        print(f"Missing exports: {missing_exports}")
    if extra_exports:
        print(f"Extra exports: {extra_exports}")

    return missing_exports == set() and extra_exports == set()
